module voting_system #(\n    parameter N = 8,\n    parameter DATA_WIDTH = 2\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [DATA_WIDTH-1:0] arr_0,\n    input wire [DATA_WIDTH-1:0] arr_1,\n    input wire [DATA_WIDTH-1:0] arr_2,\n    input wire [DATA_WIDTH-1:0] arr_3,\n    input wire [DATA_WIDTH-1:0] arr_4,\n    input wire [DATA_WIDTH-1:0] arr_5,\n    input wire [DATA_WIDTH-1:0] arr_6,\n    input wire [DATA_WIDTH-1:0] arr_7,\n    output reg done,\n    output reg impossible,\n    output reg [7:0] min_swaps\n);\n\n    // State definitions\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COUNT_TELLERS = 3'd1;\n    localparam [2:0] GENERATE_SUBSETS = 3'd2;\n    localparam [2:0] SIMULATE = 3'd3;\n    localparam [2:0] CALCULATE_COST = 3'd4;\n    localparam [2:0] UPDATE_BEST = 3'd5;\n    localparam [2:0] FINISH = 3'd6;\n\n    // Internal registers\n    reg [2:0] state;\n    reg [3:0] teller_count;\n    reg [3:0] original_teller_pos [0:N-1];\n    reg [7:0] subset_idx;\n    reg [N-1:0] current_subset;\n    reg [3:0] sim_pos;\n    reg [3:0] vote1, vote2;\n    reg [3:0] points1, points2;\n    reg [7:0] current_cost;\n    reg [7:0] best_cost;\n    reg valid_found;\n    reg [N*DATA_WIDTH-1:0] input_reg;\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            impossible <= 1'b0;\n            min_swaps <= 8'd0;\n            teller_count <= 4'd0;\n            subset_idx <= 8'd0;\n            current_subset <= 8'd0;\n            sim_pos <= 4'd0;\n            vote1 <= 4'd0;\n            vote2 <= 4'd0;\n            points1 <= 4'd0;\n            points2 <= 4'd0;\n            current_cost <= 8'd0;\n            best_cost <= 8'd255;\n            valid_found <= 1'b0;\n            input_reg <= {N{DATA_WIDTH{1'b0}}};\n            \n            // Initialize original_teller_pos array\n            integer i;\n            for (i = 0; i < N; i = i + 1) begin\n                original_teller_pos[i] <= 4'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    impossible <= 1'b0;\n                    min_swaps <= 8'd0;\n                    best_cost <= 8'd255;\n                    valid_found <= 1'b0;\n                    if (start) begin\n                        state <= COUNT_TELLERS;\n                        input_reg <= {arr_7, arr_6, arr_5, arr_4, arr_3, arr_2, arr_1, arr_0};\n                    end\n                end\n                \n                COUNT_TELLERS: begin\n                    teller_count <= 4'd0;\n                    integer i;\n                    for (i = 0; i < N; i = i + 1) begin\n                        original_teller_pos[i] <= 4'd0;\n                    end\n                    \n                    integer j;\n                    reg [3:0] pos;\n                    for (j = 0; j < N; j = j + 1) begin\n                        if (input_reg[j*DATA_WIDTH +: DATA_WIDTH] == 2'd0) begin\n                            original_teller_pos[teller_count] <= j;\n                            teller_count <= teller_count + 4'd1;\n                        end\n                    end\n                    \n                    subset_idx <= 8'd0;\n                    state <= GENERATE_SUBSETS;\n                end\n                \n                GENERATE_SUBSETS: begin\n                    if (subset_idx < 8'd256) begin\n                        current_subset <= subset_idx;\n                        sim_pos <= 4'd0;\n                        vote1 <= 4'd0;\n                        vote2 <= 4'd0;\n                        points1 <= 4'd0;\n                        points2 <= 4'd0;\n                        state <= SIMULATE;\n                    end else begin\n                        state <= FINISH;\n                    end\n                end\n                \n                SIMULATE: begin\n                    // Build target sequence and simulate election\n                    reg [DATA_WIDTH-1:0] target_seq [0:N-1];\n                    reg [3:0] non_teller_idx;\n                    integer k;\n                    \n                    non_teller_idx <= 4'd0;\n                    for (k = 0; k < N; k = k + 1) begin\n                        if (current_subset[k]) begin\n                            target_seq[k] <= 2'd0;  // Teller\n                        end else begin\n                            // Find next non-teller in input\n                            while (non_teller_idx < N && input_reg[non_teller_idx*DATA_WIDTH +: DATA_WIDTH] == 2'd0) begin\n                                non_teller_idx <= non_teller_idx + 4'd1;\n                            end\n                            if (non_teller_idx < N) begin\n                                target_seq[k] <= input_reg[non_teller_idx*DATA_WIDTH +: DATA_WIDTH];\n                                non_teller_idx <= non_teller_idx + 4'd1;\n                            end else begin\n                                target_seq[k] <= 2'd0;  // Default to teller if no more non-tellers\n                            end\n                        end\n                    end\n                    \n                    // Simulate election\n                    vote1 <= 4'd0;\n                    vote2 <= 4'd0;\n                    for (k = 0; k < N; k = k + 1) begin\n                        if (target_seq[k] == 2'd1) begin\n                            vote1 <= vote1 + 4'd1;\n                        end else if (target_seq[k] == 2'd2) begin\n                            vote2 <= vote2 + 4'd1;\n                        end\n                    end\n                    \n                    // Calculate points\n                    points1 <= 4'd0;\n                    points2 <= 4'd0;\n                    if (vote1 > vote2) begin\n                        points1 <= 4'd3;\n                        points2 <= 4'd0;\n                    end else if (vote2 > vote1) begin\n                        points1 <= 4'd0;\n                        points2 <= 4'd3;\n                    end else begin\n                        points1 <= 4'd1;\n                        points2 <= 4'd1;\n                    end\n                    \n                    state <= CALCULATE_COST;\n                end\n                \n                CALCULATE_COST: begin\n                    // Check if current subset has exactly teller_count tellers\n                    reg [3:0] subset_teller_count;\n                    integer m;\n                    subset_teller_count <= 4'd0;\n                    for (m = 0; m < N; m = m + 1) begin\n                        if (current_subset[m]) begin\n                            subset_teller_count <= subset_teller_count + 4'd1;\n                        end\n                    end\n                    \n                    if (subset_teller_count == teller_count && points1 > points2) begin\n                        // Calculate cost\n                        reg [3:0] sorted_original [0:N-1];\n                        reg [3:0] sorted_target [0:N-1];\n                        reg [3:0] temp;\n                        integer i, j;\n                        \n                        // Copy and sort original positions\n                        for (i = 0; i < N; i = i + 1) begin\n                            sorted_original[i] <= original_teller_pos[i];\n                        end\n                        \n                        // Bubble sort\n                        for (i = 0; i < N-1; i = i + 1) begin\n                            for (j = 0; j < N-i-1; j = j + 1) begin\n                                if (sorted_original[j] > sorted_original[j+1]) begin\n                                    temp <= sorted_original[j];\n                                    sorted_original[j] <= sorted_original[j+1];\n                                    sorted_original[j+1] <= temp;\n                                end\n                            end\n                        end\n                        \n                        // Find target positions\n                        integer target_idx;\n                        target_idx <= 4'd0;\n                        for (i = 0; i < N; i = i + 1) begin\n                            if (current_subset[i]) begin\n                                sorted_target[target_idx] <= i;\n                                target_idx <= target_idx + 4'd1;\n                            end\n                        end\n                        \n                        // Calculate cost\n                        current_cost <= 8'd0;\n                        for (i = 0; i < teller_count; i = i + 1) begin\n                            if (sorted_original[i] > sorted_target[i]) begin\n                                current_cost <= current_cost + (sorted_original[i] - sorted_target[i]);\n                            end else begin\n                                current_cost <= current_cost + (sorted_target[i] - sorted_original[i]);\n                            end\n                        end\n                        \n                        valid_found <= 1'b1;\n                        if (current_cost < best_cost) begin\n                            best_cost <= current_cost;\n                        end\n                    end\n                    \n                    state <= UPDATE_BEST;\n                end\n                \n                UPDATE_BEST: begin\n                    subset_idx <= subset_idx + 8'd1;\n                    state <= GENERATE_SUBSETS;\n                end\n                \n                FINISH: begin\n                    done <= 1'b1;\n                    if (valid_found) begin\n                        impossible <= 1'b0;\n                        min_swaps <= best_cost;\n                    end else begin\n                        impossible <= 1'b1;\n                        min_swaps <= 8'd0;\n                    end\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule